theorem thm_GAR : ∃ (grid : Fin 8 → Fin 8 → Bool),
  (∃ (queen_positions : Finset (Fin 8 × Fin 8)), 
    queen_positions.card = 8 ∧
    (∀ (i j : Fin 8), grid i j = true ↔ (i, j) ∈ queen_positions) ∧
    (∀ (i₁ j₁ i₂ j₂ : Fin 8), 
      grid i₁ j₁ = true → grid i₂ j₂ = true → 
      (i₁, j₁) ≠ (i₂, j₂) → 
      i₁ ≠ i₂ → j₁ ≠ j₂ → i₁ + j₁ ≠ i₂ + j₂) ∧
    (∀ i : Fin 8, (Finset.univ.filter (λ j => grid i j = true)).sum (λ j => j.val + 1) = 
      if i = 0 then 10
      else if i = 1 then 4
      else if i = 2 then 5
      else if i = 3 then 1
      else if i = 4 then 11
      else if i = 5 then 8
      else if i = 6 then 6
      else 5) ∧
    (∀ j : Fin 8, (Finset.univ.filter (λ i => grid i j = true)).sum (λ i => i.val + 1) = 
      if j = 0 then 5
      else if j = 1 then 9
      else if j = 2 then 4
      else if j = 3 then 8
      else if j = 4 then 5
      else if j = 5 then 10
      else if j = 6 then 6
      else 7)) := by
